Lemma zlength_app : forall {A} (l1 l2 : list A), zlength (l1 ++ l2) = zlength l1 + zlength l2.
Proof. intros A l1 l2. unfold zlength. rewrite length_app. lia. Qed.
Lemma zlength_firstn : forall {A} (k : nat) (l : list A), (k <= length l)%nat -> zlength (firstn k l) = Z.of_nat k.
Proof. intros A k l Hk. unfold zlength. rewrite length_firstn. lia. Qed.

Definition fb_commit (FB : fbv) (k : Z) : fbv := mkFB (fb_begin FB) (fb_in FB) (fb_out FB + k) (fb_last FB) (fb_end FB).

Definition w_after_read (w : rsw) (k : Z) : rsw :=
  mkW (w_d w) (w_PB w) (w_FBB w) (fb_commit (w_FB w) k) (w_fds w ++ firstn (Z.to_nat k) (w_sds w))
      (if zlength (w_sds w) =? 0 then w_Fs w else fb_consume (w_Fs w) k) (skipn (Z.to_nat k) (w_sds w)) (w_nr w + 1).

(* [comment removed for export] *)
Lemma rw_CB_split : forall (m : mem) A N bs k, rw_cells bsegs m A [CB N bs] -> (k <= N)%nat ->
  rw_cells bsegs m A [CB k (firstn k bs)] /\ rw_cells bsegs m (A + Z.of_nat k) [CB (N - k)%nat (skipn k bs)].
Proof.
  intros m A N bs k R LE. pose proof R as [[WF _] _]. cbn in WF. destruct WF as [L _].
  pose proof (rw_cells_split_CB bsegs m A [] N bs [] [k; (N - k)%nat] R ltac:(cbn; lia)) as R'. cbn [app mk_CB_cells] in R'.
  apply (proj1 (rw_cells_app bsegs m A [CB k (firstn k bs)] [CB (N - k)%nat (firstn (N - k) (skipn k bs))])) in R'. destruct R' as [R1 R2].
  split; [exact R1|]. cbn [cells_size csize Nat.add] in R2. rewrite Nat.add_0_r in R2. rewrite firstn_all2 in R2; [exact R2|]. rewrite length_skipn. lia.
Qed.

