(* [comment removed for export] *)
Lemma RWp_read_post : forall (C : rsc) MA (w : rsw) (k : Z),
  rs_static H C -> RWp H C MA w -> w_FB w <> FB_empty -> 0 < fb_begin (w_FB w) -> 0 <= k <= zlength (w_sds w) ->
  RWp H C MA (w_after_read w k).
Proof.
  intros C MA w k STC RP NE BP KR.
  destruct C as [bs fb P E ioc N lo B0 shi SP stb implb A LBin LF pad7 pad2 j13 j32a j8a j32b j8b mb m00 mo0 gp tp F fc MXc CXc].
  destruct w as [d PB FBB FB fds Fs sds nr]. destruct d as [c S L1 ns ls em h u es insz g rdi LBn Ag].
  unfold w_after_read, fb_commit, RWp, rs_static in *. cbn_w_all. cbn [ps_c ps_S ps_L ps_ns ps_ls ps_em ps_h ps_u ps_es ps_insz ps_g ps_rdi ps_LBn ps_A] in *.
  destruct STC as (AOP & AOE & AOF & P8 & E8 & BS8 & FB8 & SEPPE & SEPPF & SEPEF & CEIL & NR & IOC & (p7 & INS) & RBS & INA & SEPAS & LFL4 & LFL1 & TP & MXL & CXL & MB1).
  destruct RP as (PCOK & OWN & MOWN & DFB & HST & U01 & CAP & LES & INZ & LEN1 & HDJ & HL8 & SK62 & AOWN & PERM & FOK & FRL & FRB & FRT & FRM & FRF & DJL & DJB & DJT & DJM
                  & OFFP & OFFE & STRM & SZS & NRK & CPM & BY & CN & IZ & AG0 & AL).
  unfold fb_cap in *. cbn [fb_begin fb_in fb_out fb_last fb_end] in *.
  assert (ZL : zlength (fds ++ firstn (Z.to_nat k) sds) + zlength (skipn (Z.to_nat k) sds) = zlength fds + zlength sds).
  { rewrite zlength_app, zlength_firstn, zlength_skipn; unfold zlength in *; clear - KR; lia. }
  assert (NE' : {| fb_begin := fb_begin FB; fb_in := fb_in FB; fb_out := fb_out FB + k; fb_last := fb_last FB; fb_end := fb_end FB |} <> FB_empty).
  { intros EQ. pose proof (f_equal fb_begin EQ) as K. cbn in K. clear - K BP. lia. }
  split; [exact PCOK|]. split; [exact OWN|]. split; [exact MOWN|]. split; [exact DFB|].
  split; [exact HST|]. split; [exact U01|]. split; [exact CAP|]. split; [exact LES|]. split; [exact INZ|]. split; [exact LEN1|]. split; [exact HDJ|].
  split; [exact HL8|]. split; [exact SK62|]. split; [exact AOWN|]. split; [exact PERM|].
  split. { destruct FOK as [[K _] | (_ & pf & ->)]; [exfalso; exact (NE K)|]. right. split; [exact NE'|]. exists pf. reflexivity. }
  split; [exact FRL|]. split; [exact FRB|]. split; [exact FRT|]. split; [exact FRM|].
  split; [intros _; exact (FRF NE)|]. split; [intros _; exact (DJL NE)|]. split; [intros _; exact (DJB NE)|]. split; [intros _; exact (DJT NE)|]. split; [intros _; exact (DJM NE)|].
  split; [exact OFFP|]. split; [exact OFFE|].
  split.
  { destruct STRM as [[N0 EFs] | (N1 & SA & SE)].
    - left. split; [exact N0|]. replace (zlength sds =? 0) with true by (symmetry; apply Z.eqb_eq; unfold zlength in *; clear - SZS N0; lia). exact EFs.
    - right. split; [exact N1|]. destruct (zlength sds =? 0); [split; [exact SA | exact SE]|].
      pose proof (fb_consume_shape Fs k) as (CB1 & CB2 & _). rewrite CB1, CB2. split; [exact SA | exact SE]. }
  rewrite ZL. split; [exact SZS|]. split; [clear - NRK; lia|]. split; [exact CPM|]. split; [exact BY|]. split; [exact CN|]. split; [exact IZ|]. split; [exact AG0| exact AL].
Qed.

