Definition rs_at_cmp (C : rsc) (MA R : Z) (sp : word) (s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v ra : word) (fr : list cell) (M0 : Z)
    (w : rsw) (eof : bool) (cf : config) : Prop :=
  exists (rax t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (m : mem) (s : as_St H) (errv : word) (tot k : Z)
         (spa ff fp : Z) (tmp gap optc : list cell) (hw : word) (j56 j120 : list byte) (XS : list (Z * Z)),
    as_VIS H s (cfg_ms cf)
      = MS (mkR rax (wz spa) (c_gp C) (c_tp C) t0 t1 t2 sp (wz spa) (wz (if eof then 1 else 0)) a1 a2 a3 a4 a5 a6 a7
               (wz (ff + 96)) (wz tot) (wz (c_E C)) (wz k) (wz (c_E C + 16)) (wz (Z.shiftr ff 3 + 2147450880)) (wz (c_fb C + 16)) (wz 2147450880)
               (wz AGENID) (wz tot) t3 t4 t5 t6)
           (c_F C) (Z_to_bv 64 RS_CMP) (c_fc C) None m (seg_rom bsegs)
    /\ pc_state (ps_c (w_d w)) <> 11
    /\ as_AKREL H s cf /\ as_MPRES H (c_mo0 C) (cfg_model cf)
    /\ RWmF H C ((2, ff, fp) :: c_LF C) w s errv (rs_ec eof) m /\ RWp H C MA w /\ al_okR H s (ps_A (w_d w)) MA R
    /\ stk bsegs m (c_lo C) spa
    /\ rs_frames m sp spa ff fp (c_E C) (c_bs C) (c_P C) (c_fb C) (C8 (wz (Z.shiftr (c_E C + 16) 3 + 2147450880))) tmp gap hw optc j56 ect_cells j120 0
                 s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra fr
    /\ fresh_frame H (c_LF C) 2 ff fp /\ (exists me, as_RFS H (c_LF C) me)
    /\ Forall (fs_scratch H (c_LF C)) XS
    /\ (forall a, (ff <= a < ff + 256 \/ Z.shiftr ff 3 + 2147450880 <= a < Z.shiftr ff 3 + 2147450880 + 32 \/ a = fp) -> rin_ivs XS a)
    /\ xpres H (c_LBin C) (c_SP C) (hread_X (c_P C) (c_E C) (c_fb C) (c_stb C) [] [] ++ XS) (c_m0 C) m
    /\ 0 <= tot /\ tot + zlength (w_fds w) + zlength (w_sds w) <= c_N C
    /\ wM (c_N C) w <= M0
    /\ (if eof then w_sds w = [] /\ k = 0
        else 1 <= k /\ k <= fb_size (w_FB w) /\ fb_in (w_FB w) <= fb_out (w_FB w) /\ wM (c_N C) w < M0 /\ w_nr w <= c_N C - zlength (w_sds w)).

  Hypothesis FS0 : stack_malloc_0_stmt H.
